            $j = $babySteps[$current];
            $x = $i * $n + $j;
            // Verify the solution
            if (modPow($a, $x, $p) == $b % $p) {
                return $x;
            }
        }
        $current = ($current * $aInvN) % $p;
    }

    return -1;
