function modPow($base, $exp, $mod) {
    $result = 1;
    $base = $base % $mod;
    while ($exp > 0) {
        if ($exp % 2 == 1) {
            $result = ($result * $base) % $mod;
        }
        $exp = intdiv($exp, 2);
        $base = ($base * $base) % $mod;
    }
    return $result;
}

function discreteLog($a, $b, $p) {
    // Find x such that a^x ≡ b (mod p), using baby-step giant-step
    $n = (int)sqrt($p);
    // Baby steps: a^j for j = 0..n
    $babySteps = [];
    $cur = 1;
    for ($j = 0; $j <= $n; $j++) {
        if (!isset($babySteps[$cur])) {
            $babySteps[$cur] = $j;
        }
        $cur = ($cur * $a) % $p;
    }

    // Giant steps: b * (a^(-n))^i
    $aInvN = modPow(modPow($a, $n, $p), $p - 2, $p); // a^(-n) mod p
    $cur = $b;
    for ($i = 0; $i <= $n; $i++) {
        if (isset($babySteps[$cur])) {
            return $i * $n + $babySteps[$cur];
        }
        $cur = ($cur * $aInvN) % $p;
    }
    return -1;
}

